from aws_cdk import Tags
from aws_cdk.aws_organizations import CfnOrganization, CfnPolicy
from constructs import Construct


class RequireResourceTagsPolicy(Construct):
    """Require mandatory tags on S3 buckets, EC2 instances, and RDS clusters.

    This policy enforces organizational tagging standards by requiring all S3 buckets,
    EC2 instances, and RDS clusters to be tagged with 'CostCenter', 'DataClassification',
    and 'Owner'. This ensures better resource tracking, cost allocation, and ownership clarity.

    Security and Operational Benefits:
        - Enforces consistent tagging across the organization for resource governance
        - Enables accurate cost allocation and chargeback through CostCenter tags
        - Clarifies data sensitivity through DataClassification tags
        - Establishes clear ownership and accountability through Owner tags
        - Prevents untagged resources that could bypass compliance and cost controls
        - Improves resource discovery, management, and compliance auditing
    """

    def __init__(
        self,
        scope: Construct,
        organization: CfnOrganization,
        **kwargs,
    ):
        super().__init__(scope, "RequireResourceTagsPolicy", **kwargs)

        # Create the policy document that requires tags on resource creation
        policy_document = {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "DenyS3BucketWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": [
                        "s3:CreateBucket",
                    ],
                    "Resource": "arn:aws:s3:::*",
                    "Condition": {
                        "StringNotLike": {
                            "aws:RequestTag/CostCenter": "*",
                            "aws:RequestTag/DataClassification": "*",
                            "aws:RequestTag/Owner": "*",
                        }
                    },
                },
                {
                    "Sid": "DenyEC2InstanceWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": [
                        "ec2:RunInstances",
                    ],
                    "Resource": [
                        "arn:aws:ec2:*:*:instance/*",
                    ],
                    "Condition": {
                        "StringNotLike": {
                            "aws:RequestTag/CostCenter": "*",
                            "aws:RequestTag/DataClassification": "*",
                            "aws:RequestTag/Owner": "*",
                        }
                    },
                },
                {
                    "Sid": "DenyRDSClusterWithoutRequiredTags",
                    "Effect": "Deny",
                    "Action": [
                        "rds:CreateDBCluster",
                    ],
                    "Resource": "arn:aws:rds:*:*:cluster:*",
                    "Condition": {
                        "StringNotLike": {
                            "aws:RequestTag/CostCenter": "*",
                            "aws:RequestTag/DataClassification": "*",
                            "aws:RequestTag/Owner": "*",
                        }
                    },
                },
            ],
        }

        # Create the SCP in AWS Organizations
        scp = CfnPolicy(
            self,
            "RequireResourceTagsPolicy",
            content=policy_document,
            description=(
                "Require CostCenter, DataClassification, and Owner tags on S3 buckets, "
                "EC2 instances, and RDS clusters"
            ),
            name="Require-Resource-Tags",
            type="SERVICE_CONTROL_POLICY",
        )

        scp.target_ids = [organization.attr_root_id]

        # Tag the policy for easier identification and management
        Tags.of(scp).add("Purpose", "Governance")
        Tags.of(scp).add("SecurityControl", "ResourceTagging")

