from aws_cdk import Tags
from aws_cdk.aws_organizations import CfnOrganization, CfnPolicy
from constructs import Construct


class RequireResourceTagsPolicy(Construct):
    """Enforce tagging requirements for S3, EC2, and RDS resources.

    This policy denies creation of S3 buckets, EC2 instances, and RDS clusters
    unless they are tagged with the required tags: CostCenter, DataClassification,
    and Owner. This ensures proper resource tracking, cost allocation, and security
    classification across all resources.

    Security Risk Mitigation:
        Enforcing resource tags helps with:
        - Cost tracking and chargeback through CostCenter tags
        - Security classification and compliance through DataClassification tags
        - Accountability and incident response through Owner tags
        - Preventing untagged "rogue" resources that bypass organizational controls

        Without this control, teams could:
        - Create untracked resources that bypass cost allocations
        - Avoid applying appropriate security classifications
        - Create resources without clear ownership for incident response
        - Make it difficult to track and audit all resources in use
    """

    def __init__(
        self,
        scope: Construct,
        organization: CfnOrganization,
        **kwargs,
    ):
        super().__init__(scope, "RequireResourceTagsPolicy", **kwargs)

        # Required tag keys
        required_tags = ["CostCenter", "DataClassification", "Owner"]

        # Build condition block for tags
        # This checks that all required tags are present when creating resources
        tag_condition = {}
        for tag in required_tags:
            tag_condition[f"aws:RequestTag/{tag}"] = ["*"]

        # Create the policy document that requires tags on resource creation
        policy_document = {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "DenyS3CreateWithoutTags",
                    "Effect": "Deny",
                    "Action": [
                        "s3:CreateBucket",
                    ],
                    "Resource": "arn:aws:s3:::*",
                    "Condition": {
                        "StringNotLike": tag_condition,
                    },
                },
                {
                    "Sid": "DenyEC2InstanceWithoutTags",
                    "Effect": "Deny",
                    "Action": [
                        "ec2:RunInstances",
                    ],
                    "Resource": [
                        "arn:aws:ec2:*:*:instance/*",
                    ],
                    "Condition": {
                        "StringNotLike": tag_condition,
                    },
                },
                {
                    "Sid": "DenyRDSClusterWithoutTags",
                    "Effect": "Deny",
                    "Action": [
                        "rds:CreateDBCluster",
                    ],
                    "Resource": "arn:aws:rds:*:*:cluster/*",
                    "Condition": {
                        "StringNotLike": tag_condition,
                    },
                },
                {
                    "Sid": "DenyRDSInstanceWithoutTags",
                    "Effect": "Deny",
                    "Action": [
                        "rds:CreateDBInstance",
                    ],
                    "Resource": "arn:aws:rds:*:*:db/*",
                    "Condition": {
                        "StringNotLike": tag_condition,
                    },
                },
            ],
        }

        # Create the SCP in AWS Organizations
        scp = CfnPolicy(
            self,
            "RequireResourceTagsPolicy",
            content=policy_document,
            description="Enforce required tags (CostCenter, DataClassification, Owner) on S3 buckets, EC2 instances, and RDS clusters.",
            name="Require-Resource-Tags",
            type="SERVICE_CONTROL_POLICY",
        )

        scp.target_ids = [organization.attr_root_id]

        # Tag the policy for easier identification and management
        Tags.of(scp).add("Purpose", "Security")
        Tags.of(scp).add("SecurityControl", "ResourceTagging")

