from aws_cdk import CfnOutput
from aws_cdk import aws_budgets as budgets
from aws_cdk import aws_sns as sns
from constructs import Construct


class BillingAlarm(Construct):
    """Billing alarm component for monitoring organizational spend.

    This component creates an AWS Budget that monitors monthly spend and triggers
    alerts when spend exceeds $100M or is forecasted to exceed $100M. Notifications
    are sent to an SNS topic for alerting.
    """

    def __init__(self, scope: Construct, **kwargs):
        super().__init__(scope, "BillingAlarm", **kwargs)

        # SNS Topic for billing alarms
        self.billing_alarm_topic = sns.Topic(
            self, "BillingAlarmTopic", display_name="org-billing-alarms"
        )

        # Create a budget for monitoring organizational spend
        # The budget monitors the entire organization (all accounts)
        budget = budgets.CfnBudget(
            self,
            "OrganizationBudget",
            budget={
                "budget_name": "Organization-Monthly-Spend",
                "budget_limit": {
                    "amount": "100000000",  # $100M
                    "unit": "USD",
                },
                "time_period": {
                    "start": "2024-01-01T00:00:00.000Z",
                    "end": "2099-12-31T23:59:59.999Z",
                },
                "time_unit": "MONTHLY",
                "budget_type": "COST",
                "cost_filters": {
                    # This budget applies to all linked accounts in the organization
                    "LinkedAccount": ["*"]
                },
            },
            # Notification thresholds
            notifications_with_subscribers=[
                {
                    "notification": {
                        "comparison_operator": "GREATER_THAN",
                        "notification_type": "ACTUAL",
                        "threshold": 100,
                        "threshold_type": "PERCENTAGE",
                    },
                    "subscribers": [
                        {
                            "address": self.billing_alarm_topic.topic_arn,
                            "subscription_type": "SNS",
                        }
                    ],
                },
                {
                    "notification": {
                        "comparison_operator": "GREATER_THAN",
                        "notification_type": "FORECASTED",
                        "threshold": 100,
                        "threshold_type": "PERCENTAGE",
                    },
                    "subscribers": [
                        {
                            "address": self.billing_alarm_topic.topic_arn,
                            "subscription_type": "SNS",
                        }
                    ],
                },
            ],
        )

        # Output the SNS topic ARN for external subscription
        CfnOutput(
            self,
            "BillingAlarmSNSTopicArn",
            description="Billing alarm SNS topic ARN for subscription.",
            value=self.billing_alarm_topic.topic_arn,
        )

