from aws_cdk import CfnOutput
from aws_cdk import aws_budgets as budgets
from aws_cdk import aws_sns as sns
from constructs import Construct


class BillingAlarm(Construct):
    """Monitor organizational spending and send alerts when budget thresholds are exceeded.

    This component creates an AWS Budget that monitors monthly spending at the organization level
    and sends SNS notifications whenever:
    - Actual spend exceeds $100M in a month
    - Forecasted spend is expected to exceed $100M in a month

    The budget is configured to alert at 100% of the $100M threshold using both ACTUAL and
    FORECASTED comparison types.
    """

    def __init__(self, scope: Construct, **kwargs):
        super().__init__(scope, "BillingAlarm", **kwargs)

        # SNS Topic for billing alarms
        self.billing_alarm_topic = sns.Topic(
            self, "BillingAlarmTopic", display_name="org-billing-alarms"
        )

        # Create a budget for organizational spending
        budget = budgets.CfnBudget(
            self,
            "OrganizationBudget",
            budget={
                "budgetName": "organization-monthly-budget",
                "budgetLimit": {
                    "amount": "100000000",  # $100M
                    "unit": "USD",
                },
                "timeUnit": "MONTHLY",
                "budgetType": "COST",
                "costFilters": {
                    # Monitor all costs across the organization
                    "Service": ["Amazon Elastic Compute Cloud - Compute"],
                },
            },
            notification_with_subscribers_list=[
                {
                    "notification": {
                        "notificationType": "ACTUAL",
                        "comparisonOperator": "GREATER_THAN",
                        "threshold": 100,  # 100% of $100M
                        "thresholdType": "PERCENTAGE",
                    },
                    "subscribers": [
                        {
                            "subscriptionType": "SNS",
                            "address": self.billing_alarm_topic.topic_arn,
                        }
                    ],
                },
                {
                    "notification": {
                        "notificationType": "FORECASTED",
                        "comparisonOperator": "GREATER_THAN",
                        "threshold": 100,  # 100% of $100M
                        "thresholdType": "PERCENTAGE",
                    },
                    "subscribers": [
                        {
                            "subscriptionType": "SNS",
                            "address": self.billing_alarm_topic.topic_arn,
                        }
                    ],
                },
            ],
        )

        # Output the SNS topic ARN for subscription/reference
        CfnOutput(
            self,
            "BillingAlarmTopicArn",
            description="SNS topic ARN for billing alarm subscriptions.",
            value=self.billing_alarm_topic.topic_arn,
        )

